*/

#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;string.h&gt;
#include "config.h"

//
// Global Data
//

extern int phase(char *inputs);

extern const char* phase_id;

//
// Declarations
//

char inputs[256];

//
// Utilities
// 

void fixinput( char* inputs, int length )
{
    char *p;
    for ( p = inputs+length-1; p &gt;= inputs; p -- )
        if ( *p == '\n' )  *p = '\0';
}

//
// Main Function
// 

int main( int argc, const char* argv[] )
{
#if defined(QUESTION)
    FILE *stream = 0;

    // If no command argument is given, read the input line from standard input.
    if (argc == 1)
        stream = stdin;
    else // When a file argument is given, read the input line from the file.
    if (argc == 2)
    {
        stream = fopen(argv[1], "r");
        if (! stream) {
            printf("Error: Failed to open the file %s.\n", argv[1]);
            exit(1);
        }
    }
    else // More than one command line arguments are not allowed.
    {
        printf("Usage: %s [input file]\n", argv[0]);
        exit(1);
    }

    printf("Welcome to the binary program analysis lab.\n");
    printf("Here begins the task. Please input your answer ...\n");

    // Read the input line
    memset(inputs, 0, sizeof(inputs));
    if (! fgets(inputs, sizeof(inputs), stream)) {
        printf("Error: Failed to read the input line.\n");
        exit(1);
    }
    fixinput(inputs, sizeof(inputs));

    // Run the phase
    if ( phase(inputs) )
        printf("Congratulations! You've completed %s successfully.\n", phase_id);
    else
        printf("Oops, %s failed. Try again.\n", phase_id);

#elif defined(ANSWER)
    memset(inputs, 0, sizeof(inputs));
    phase(inputs);

#endif

    return 0;
}
</code></pre> <p>C 语言还是很好理解的，可以读取标准输入，也可以读取文件作为某个 Phase 的输入；宏定义 <code>QUESTION</code> 有效时，进行正常的测试；宏定义为 <code>ANSWER</code> 时生成答案（这个我们用不到）</p> <p>但是在阅读汇编代码时，我们首先会发现一个问题：我们的输入储存在了哪里（换句话说，输入内容的首地址在哪个寄存器内被储存）</p> <p>汇编代码中 <code>&lt;main&gt;</code> 函数有这样一个部分（以 Phase 1 为例）：</p> <pre><code>40085f: e8 b9 fe ff ff          call   40071d &lt;fixinput&gt;
400864: bf 40 11 60 00          mov    $0x601140,%edi
400869: e8 5c 00 00 00          call   4008ca &lt;phase&gt;
</code></pre> <p><code>&lt;fixinput&gt;</code> 函数用于将字符串输入结尾的 <code>\n</code> 替换为 <code>\0</code>，而在调用 <code>&lt;phase&gt;</code> 函数之前的 <code>mov</code> 操作将输入首地址 <code>$0x601140</code> 赋值给了 <code>%edi</code>，因此在接下来的 Phase 中，用户输入的首地址是由 <code>%rdi</code> 传入的（至于理解传入后的压栈等操作，那是 Phase 内的任务）</p> <p>另外，如果你看到了一些看上去把简单的事情复杂化的代码片段，那是编译器不执行任何优化的结果，比如 Phase 1 的 <code>%rdi</code> 传递</p> <p>另另外，如果你发现了 <code>&lt;__func_DumwPqNk&gt;</code> 这样的什么都不做的函数，那大概率是给每个学生的作业标记</p> <p></p>
